import os
import hashlib
import hmac
import unicodedata
import re
from pathlib import PurePosixPath
from typing import Optional, Tuple

# Configuration
SECRET_KEY = os.environ.get('APP_SECRET')
if not SECRET_KEY:
    raise RuntimeError(
        "APP_SECRET environment variable must be set to a strong secret; "
        "refusing to start with an insecure default key."
    )
BASE_CONTENT_DIR = '/var/www/content'
ALLOWED_EXTENSIONS = {'.txt', '.md', '.html', '.css', '.js', '.json', '.png', '.jpg'}
MAX_PATH_LENGTH = 256


class PathValidator:
    """Validates and sanitizes file paths for the content server."""

    # Block obvious traversal patterns
    TRAVERSAL_PATTERNS = [
        re.compile(r'\.\./'),
        re.compile(r'/\.\./'),
        re.compile(r'\.\.\\'),
        re.compile(r'\\\.\.'),
    ]

    # Block null bytes and control characters
    DANGEROUS_CHARS = re.compile(r'[\x00-\x1f\x7f]')

    def __init__(self, base_dir: str):
        self._base_dir = os.path.realpath(base_dir)

    def _check_traversal(self, path: str) -> bool:
        """Returns True if path contains traversal sequences."""
        for pattern in self.TRAVERSAL_PATTERNS:
            if pattern.search(path):
                return True
        # Also check decoded form
        if '..' in path.split('/'):
            return True
        return False

    def _check_extension(self, path: str) -> bool:
        """Returns True if extension is allowed."""
        ext = PurePosixPath(path).suffix.lower()
        return ext in ALLOWED_EXTENSIONS

    def _check_dangerous_chars(self, path: str) -> bool:
        """Returns True if path contains dangerous characters."""
        return bool(self.DANGEROUS_CHARS.search(path))

    def validate_and_resolve(self, user_path: str) -> Tuple[bool, Optional[str], str]:
        """Validate user-supplied path and resolve to absolute path.

        Returns (is_valid, resolved_path, error_message)
        """
        if not user_path:
            return False, None, "Empty path"

        if len(user_path) > MAX_PATH_LENGTH:
            return False, None, "Path too long"

        # Strip leading/trailing whitespace
        cleaned = user_path.strip()

        # Remove leading slashes to make relative
        cleaned = cleaned.lstrip('/')

        # Normalize Unicode FIRST before any security checks
        # This prevents bypass via equivalent Unicode representations
        cleaned = unicodedata.normalize('NFC', cleaned)

        # Check for dangerous characters
        if self._check_dangerous_chars(cleaned):
            return False, None, "Invalid characters in path"

        # Check for traversal attempts
        if self._check_traversal(cleaned):
            return False, None, "Path traversal detected"

        # Check extension
        if not self._check_extension(cleaned):
            return False, None, "File type not allowed"

        # Resolve the full path
        full_path = os.path.join(self._base_dir, cleaned)
        resolved = os.path.realpath(full_path)

        # Final containment check
        if not resolved.startswith(self._base_dir + os.sep):
            return False, None, "Access denied"

        return True, resolved, ""


class AuthToken:
    """HMAC-based authentication tokens."""

    @staticmethod
    def generate(user_id: str, role: str) -> str:
        payload = f"{user_id}:{role}"
        sig = hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()
        return f"{payload}:{sig}"

    @staticmethod
    def verify(token: str) -> Optional[Tuple[str, str]]:
        parts = token.rsplit(':', 1)
        if len(parts) != 2:
            return None
        payload, sig = parts
        expected = hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(sig, expected):
            return None
        user_parts = payload.split(':', 1)
        if len(user_parts) != 2:
            return None
        return user_parts[0], user_parts[1]


class ContentServer:
    """Serves static content files with path validation."""

    def __init__(self):
        self._validator = PathValidator(BASE_CONTENT_DIR)
        self._access_log = []

    def serve_file(self, request_path: str, auth_token: str) -> dict:
        """Main entry point for file serving requests."""
        # Verify authentication
        auth_result = AuthToken.verify(auth_token)
        if auth_result is None:
            return {"status": 401, "error": "Invalid authentication"}

        user_id, role = auth_result

        # Validate and resolve path
        is_valid, resolved_path, error = self._validator.validate_and_resolve(request_path)

        if not is_valid:
            self._access_log.append({
                "user": user_id,
                "path": request_path,
                "denied": True,
                "reason": error
            })
            return {"status": 403, "error": error}

        # Check file exists
        if not os.path.isfile(resolved_path):
            return {"status": 404, "error": "File not found"}

        # Read and return content
        try:
            with open(resolved_path, 'rb') as f:
                content = f.read()
            self._access_log.append({
                "user": user_id,
                "path": resolved_path,
                "denied": False
            })
            return {"status": 200, "content": content, "path": resolved_path}
        except IOError as e:
            return {"status": 500, "error": "Read error"}


def handle_request(method: str, path: str, headers: dict, body: dict) -> dict:
    """HTTP request handler."""
    if method != 'GET':
        return {"status": 405, "error": "Method not allowed"}

    auth_header = headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return {"status": 401, "error": "Missing authorization"}

    token = auth_header[7:]
    server = ContentServer()
    return server.serve_file(path, token)
